/*
 * CozyNook sprite engine
 * ----------------------
 * Draws the layered pixel-art character and the animated cat onto small
 * <canvas> elements, which CSS scales up with crisp "pixelated" rendering.
 *
 * The sprite sheets live in assets/sprites/ and are generated by
 * tools/build_sprites.py.  Colours that the player can customise (skin,
 * hair, outfit, cat coat) are "key" colours in the PNGs and get swapped here.
 *
 * Public API (window.CozySprites):
 *   setLook(state)            update character + cat look from the save state
 *   portrait(element)         draw a small head portrait into an element
 *   catPreview(coatKey)       canvas showing a cat in the given coat
 *   CAT_COATS                 list of [key, label] coat choices
 */
(function () {
  'use strict';
  var META = window.COZY_SPRITE_META;
  if (!META) { console.warn('CozyNook: sprite metadata missing'); return; }

  var BASE = 'assets/sprites/';
  var CW = META.cell[0], CH = META.cell[1], COLS = META.cols;
  var KW = META.cat.cell[0], KH = META.cat.cell[1];
  var HEAD = META.head || [3, 0, 26, 24];          // head crop for portraits
  var FEET = META.feet || (CH - 2);               // row of the character's feet
  var CAT_FEET = META.cat.feet || (KH - 4);
  var IW = META.icons.cell[0];

  // ---------------------------------------------------------------- colour helpers
  function rgb(hex) {
    hex = hex.replace('#', '');
    if (hex.length === 3) hex = hex.split('').map(function (c) { return c + c; }).join('');
    return [parseInt(hex.slice(0, 2), 16), parseInt(hex.slice(2, 4), 16), parseInt(hex.slice(4, 6), 16)];
  }
  function mix(a, b, t) {
    var A = rgb(a), B = rgb(b);
    return '#' + A.map(function (v, i) {
      return Math.round(v + (B[i] - v) * t).toString(16).padStart(2, '0');
    }).join('');
  }
  var shade = function (c, t) { return mix(c, '#3a2046', t); };   // purple-ish shadows look nicer than grey
  var light = function (c, t) { return mix(c, '#fff4dc', t); };

  var CAT_COATS = [
    ['ginger', 'Ginger tabby', { f: '#f2a65a', F: '#c97a3a', g: '#ffd09a', d: '#b0612c', z: '#fff3e2', Z: '#e8d2bd' }],
    ['grey', 'Grey tabby', { f: '#a9adbd', F: '#7d8197', g: '#ccd0dc', d: '#676b82', z: '#f6f2ec', Z: '#d8d3cc' }],
    ['tuxedo', 'Tuxedo', { f: '#4a4459', F: '#332e40', g: '#6a6380', d: '#332e40', z: '#fff6ea', Z: '#e0d2c4' }],
    ['snow', 'Snowball', { f: '#fbf1e4', F: '#e3cfb8', g: '#ffffff', d: '#f0d9c0', z: '#ffffff', Z: '#efe3d6' }],
    ['cocoa', 'Cocoa', { f: '#8f5d45', F: '#68412f', g: '#ad7c61', d: '#5c3828', z: '#f4dcc4', Z: '#d8bea4' }],
    ['blue', 'Blue moon', { f: '#7d8fb8', F: '#5b6b94', g: '#a3b3d6', d: '#56658c', z: '#eef0fb', Z: '#cfd4e8' }]
  ];

  function characterPalette(st) {
    var skin = st.skin || '#efbd9d', hair = st.hair || '#67483d', cloth = st.outfit || '#91a477';
    return {
      s: skin, S: shade(skin, 0.22), q: light(skin, 0.4), b: mix(skin, '#e8607a', 0.45),
      h: hair, H: shade(hair, 0.32), l: light(hair, 0.22),
      c: cloth, C: shade(cloth, 0.26), L: light(cloth, 0.3)
    };
  }
  function catPalette(key) {
    for (var i = 0; i < CAT_COATS.length; i++) if (CAT_COATS[i][0] === key) return CAT_COATS[i][2];
    return CAT_COATS[0][2];
  }

  // ---------------------------------------------------------------- image loading + recolouring
  var images = {}, loaded = 0, NEED = 3, onReady = [];
  ['character-layers', 'cat', 'emote-icons'].forEach(function (name) {
    var img = new Image();
    img.onload = function () { loaded++; if (loaded === NEED) onReady.forEach(function (f) { f(); }); };
    img.onerror = function () { console.warn('CozyNook: could not load sprite sheet ' + name); };
    img.src = BASE + name + '.png';
    images[name] = img;
  });
  function ready() { return loaded === NEED; }

  var recolourCache = {};
  // Returns a canvas copy of the sheet with key colours swapped.
  // If the browser blocks pixel access (e.g. opening the file directly from
  // disk) we fall back to the original sheet, which uses the default colours.
  function recoloured(sheetName, palette) {
    var cacheKey = sheetName + JSON.stringify(palette);
    if (recolourCache[cacheKey]) return recolourCache[cacheKey];
    var img = images[sheetName];
    var c = document.createElement('canvas');
    c.width = img.naturalWidth; c.height = img.naturalHeight;
    var ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0);
    try {
      var data = ctx.getImageData(0, 0, c.width, c.height);
      var px = data.data, map = {};
      Object.keys(palette).forEach(function (k) {
        if (!META.keys[k]) return;
        var from = rgb(META.keys[k]);
        map[(from[0] << 16) | (from[1] << 8) | from[2]] = rgb(palette[k]);
      });
      for (var i = 0; i < px.length; i += 4) {
        if (!px[i + 3]) continue;
        var to = map[(px[i] << 16) | (px[i + 1] << 8) | px[i + 2]];
        if (to) { px[i] = to[0]; px[i + 1] = to[1]; px[i + 2] = to[2]; }
      }
      ctx.putImageData(data, 0, 0);
    } catch (err) {
      c = img;
    }
    recolourCache[cacheKey] = c;
    return c;
  }

  function layerXY(name) {
    var i = META.layers[name];
    if (i === undefined) return null;
    return [(i % COLS) * CW, Math.floor(i / COLS) * CH];
  }

  // ---------------------------------------------------------------- character drawing
  var look = { gender: 'girl', emote: 'happy', outfitStyle: 'hoodie', hairStyle: 'default', accessory: 'none' };

  function layerList(blink, step) {
    var g = look.gender === 'boy' ? 'boy' : 'girl';
    var hs = look.hairStyle || 'default';
    var hk = hs === 'default' ? 'default-' + g : hs;
    var emote = look.emote || 'happy';
    var faceName = blink ? 'face-' + emote + '-blink' : 'face-' + emote + (g === 'girl' ? '-girl' : '');
    var sfx = step ? '@w' + step : '';
    var list = ['hairback-' + hk, 'body' + sfx, 'outfit-' + (look.outfitStyle || 'hoodie') + sfx, faceName, 'hairfront-' + hk];
    var acc = look.accessory;
    if (acc && acc !== 'none') {
      list.push('acc-' + acc);
    }
    return list;
  }

  // Draws the character at (ox, oy).  headDy pushes the head down (breathing).
  function drawCharacter(ctx, ox, oy, blink, headDy, step) {
    var sheet = recoloured('character-layers', characterPalette(look));
    var SPLIT = META.split || 22;   // rows above this belong to the head
    layerList(blink, step).forEach(function (name) {
      var p = layerXY(name);
      if (!p) return;
      // body / lower half
      ctx.drawImage(sheet, p[0], p[1] + SPLIT, CW, CH - SPLIT, ox, oy + SPLIT, CW, CH - SPLIT);
      // head / upper half
      ctx.drawImage(sheet, p[0], p[1], CW, SPLIT, ox, oy + headDy, CW, SPLIT);
    });
  }

  function drawIcon(ctx, emote, x, y) {
    var idx = META.icons.order.indexOf(emote);
    if (idx < 0) return;
    // little speech bubble behind the icon
    ctx.fillStyle = '#3a2630';
    ctx.fillRect(x + 1, y, IW + 2, IW + 4);
    ctx.fillRect(x, y + 1, IW + 4, IW + 2);
    ctx.fillStyle = '#fff8ec';
    ctx.fillRect(x + 1, y + 1, IW + 2, IW + 2);
    ctx.fillStyle = '#3a2630';
    ctx.fillRect(x + 2, y + IW + 4, 2, 2);
    ctx.fillRect(x + 1, y + IW + 6, 1, 1);
    ctx.drawImage(images['emote-icons'], idx * IW, 0, IW, IW, x + 2, y + 2, IW, IW);
  }

  // ---------------------------------------------------------------- room character widget
  var CHAR_OX = 6, CHAR_OY = 18, CHAR_W = CW + CHAR_OX * 2, CHAR_H = CH + CHAR_OY;
  var charCanvas = null, charState = { breathe: 0, blinkUntil: 0, nextBlink: 0, hop: [], iconBob: 0 };

  function ensureCharacterCanvas() {
    var host = document.getElementById('roomCharacter');
    if (!host) return null;
    if (!charCanvas || charCanvas.parentNode !== host) {
      charCanvas = document.createElement('canvas');
      charCanvas.width = CHAR_W; charCanvas.height = CHAR_H;
      charCanvas.className = 'sprite-canvas';
      host.appendChild(charCanvas);
      host.addEventListener('click', function () { hopCharacter(); });
    }
    return charCanvas;
  }
  function hopCharacter() { charState.hop = [-2, -4, -5, -4, -2, 0, -1, 0]; }

  // Walking: the character strolls left and right along the floor.
  var ROOM_W = 320, ROOM_H = 180, WALK_MIN = 40, WALK_MAX = 262, FEET_MIN = 132, FEET_MAX = 172, WALK_SPEED = 16;   // room pixels per second
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var walker = { x: 200, y: 156, target: 200, targetY: 156, facing: 1, restUntil: 0, last: 0 };
  var charBuffer = null;

  function placeWalker() {
    var host = document.getElementById('roomCharacter');
    if (!host) return;
    host.style.left = (walker.x / ROOM_W * 100).toFixed(3) + '%';
    // the canvas bottom sits 2px below the feet
    host.style.bottom = ((ROOM_H - (walker.y + (CHAR_H - CHAR_OY - FEET))) / ROOM_H * 100).toFixed(3) + '%';
    // depth: walk behind the cat when further back in the room
    var catEl = document.getElementById('sleepyCat');
    var catFeet = 146;
    if (catEl && catEl.style.bottom) catFeet = ROOM_H - parseFloat(catEl.style.bottom) / 100 * ROOM_H - (CAT_H - CAT_OY - CAT_FEET);
    host.style.zIndex = walker.y < catFeet ? '5' : '7';
  }

  function updateWalker(now) {
    var dt = walker.last ? Math.min(0.25, (now - walker.last) / 1000) : 0;
    walker.last = now;
    if (!walker.placed) { placeWalker(); walker.placed = true; }
    if (reduceMotion || document.querySelector('.room-decor-item.is-dragging')) return false;
    var dx = walker.target - walker.x, dy = walker.targetY - walker.y;
    var dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < 0.5) {
      walker.x = walker.target; walker.y = walker.targetY;
      if (!walker.restUntil) walker.restUntil = now + 4000 + Math.random() * 7000;
      if (now > walker.restUntil) {
        var t, ty;
        do {
          t = WALK_MIN + Math.random() * (WALK_MAX - WALK_MIN);
          ty = FEET_MIN + Math.random() * (FEET_MAX - FEET_MIN);
        } while (Math.abs(t - walker.x) + Math.abs(ty - walker.y) < 40);
        walker.target = Math.round(t); walker.targetY = Math.round(ty);
        walker.restUntil = 0;
      }
      return false;
    }
    if (Math.abs(dx) > 0.5) walker.facing = dx > 0 ? 1 : -1;
    var step = Math.min(dist, WALK_SPEED * dt);
    walker.x += dx / dist * step;
    walker.y += dy / dist * step;
    placeWalker();
    return true;
  }

  function renderCharacter(now) {
    var c = ensureCharacterCanvas();
    if (!c || !ready()) return;
    var ctx = c.getContext('2d');
    ctx.clearRect(0, 0, CHAR_W, CHAR_H);
    if (now > charState.nextBlink) {
      charState.blinkUntil = now + 150;
      charState.nextBlink = now + 2400 + Math.random() * 3200;
    }
    var blink = now < charState.blinkUntil;
    var walking = charState.hop.length ? false : updateWalker(now);
    var phase = Math.floor(now / 170) % 4;
    var step = walking ? [1, 0, 2, 0][phase] : 0;
    var headDy = walking ? 0 : Math.floor(now / 700) % 2;
    var hopY = charState.hop.length ? charState.hop.shift() : (walking && phase % 2 === 0 ? -1 : 0);
    // soft floor shadow
    ctx.fillStyle = 'rgba(58,38,48,.22)';
    ctx.fillRect(CHAR_OX + CW / 2 - 10, CHAR_OY + FEET - 1, 20, 2);
    ctx.fillRect(CHAR_OX + CW / 2 - 12, CHAR_OY + FEET, 24, 1);
    // draw into a buffer so we can mirror it when walking left
    if (!charBuffer) { charBuffer = document.createElement('canvas'); charBuffer.width = CW; charBuffer.height = CH; }
    var b = charBuffer.getContext('2d');
    b.clearRect(0, 0, CW, CH);
    drawCharacter(b, 0, 0, blink, headDy, step);
    ctx.save();
    if (walker.facing < 0) {
      ctx.translate(CHAR_OX * 2 + CW, 0);
      ctx.scale(-1, 1);
    }
    ctx.drawImage(charBuffer, CHAR_OX, CHAR_OY + hopY);
    ctx.restore();
    var bob = Math.floor(now / 500) % 2;
    drawIcon(ctx, look.emote || 'happy', CHAR_W - 18, 1 + bob + Math.min(0, hopY));
  }

  // ---------------------------------------------------------------- cat widget
  var CAT_OX = 4, CAT_OY = 16, CAT_W = KW + CAT_OX * 2, CAT_H = KH + CAT_OY;
  var catCanvas = null;
  var cat = { mode: 'sit', since: 0, until: 0, nextBlink: 0, blinkUntil: 0, coat: 'ginger', hop: [], hearts: [] };

  function frameXY(name) {
    var i = META.cat.frames.indexOf(name);
    return i < 0 ? 0 : i * KW;
  }
  function ensureCatCanvas() {
    var host = document.getElementById('sleepyCat');
    if (!host) return null;
    if (!catCanvas || catCanvas.parentNode !== host) {
      catCanvas = document.createElement('canvas');
      catCanvas.width = CAT_W; catCanvas.height = CAT_H;
      catCanvas.className = 'sprite-canvas';
      host.appendChild(catCanvas);
      host.addEventListener('click', petCat);
      host.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') petCat(); });
    }
    return catCanvas;
  }
  // If a cat bed is placed in the room, the cat curls up in it for naps.
  function moveCatToBed(goToBed) {
    var host = document.getElementById('sleepyCat');
    if (!host) return;
    var bedArt = goToBed && document.querySelector('.room-decor-item .pixel-decor-catbed');
    if (bedArt) {
      var item = bedArt.closest('.room-decor-item');
      var left = parseFloat(item.style.left), top = parseFloat(item.style.top);
      if (isNaN(left) || isNaN(top)) return;
      // cushion sits ~3px above the item's centre; the sleeping cat's body ends 7px above the canvas bottom
      var RH = (ROOM && ROOM.size[1]) || 180;
      var cushionY = top / 100 * RH + 4;
      host.style.left = (left + 1).toFixed(2) + '%';
      host.style.bottom = ((RH - (cushionY + (CAT_H - CAT_OY - (META.cat.loafBottom || KH - 2)))) / RH * 100).toFixed(2) + '%';
      host.style.zIndex = '8';
      cat.inBed = true;
    } else {
      host.style.left = ''; host.style.bottom = ''; host.style.zIndex = '';
      cat.inBed = false;
    }
  }

  function petCat() {
    var now = performance.now();
    cat.mode = 'happy'; cat.since = now; cat.until = now + 1600;
    cat.hop = [-2, -4, -4, -2, 0, 0, -2, -3, -2, 0];
    cat.hearts.push({ x: CAT_W * 0.2 + Math.random() * 8, born: now }, { x: CAT_W * 0.5 + Math.random() * 8, born: now + 250 });
  }
  function drawHeart(ctx, x, y) {
    ctx.fillStyle = '#3a2630';
    ctx.fillRect(x, y + 1, 7, 3); ctx.fillRect(x + 1, y, 2, 5); ctx.fillRect(x + 4, y, 2, 5);
    ctx.fillRect(x + 2, y + 4, 3, 2); ctx.fillRect(x + 3, y + 6, 1, 1);
    ctx.fillStyle = '#ec5f7e';
    ctx.fillRect(x + 1, y + 1, 2, 3); ctx.fillRect(x + 4, y + 1, 2, 3); ctx.fillRect(x + 2, y + 2, 3, 3); ctx.fillRect(x + 3, y + 5, 1, 1);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(x + 1, y + 1, 1, 1);
  }
  function drawZ(ctx, x, y, s) {
    ctx.fillStyle = '#4f97c2';
    ctx.fillRect(x, y, s, 1); ctx.fillRect(x, y + s - 1, s, 1);
    for (var i = 1; i < s - 1; i++) ctx.fillRect(x + s - 1 - i, y + i, 1, 1);
  }

  function renderCat(now) {
    var c = ensureCatCanvas();
    if (!c || !ready()) return;
    var ctx = c.getContext('2d');
    ctx.clearRect(0, 0, CAT_W, CAT_H);
    if (!cat.since) { cat.since = now; cat.until = now + 18000 + Math.random() * 12000; }

    // simple behaviour loop: sit and look around -> curl up for a nap -> wake up
    if (cat.mode === 'happy' && now > cat.until) { cat.mode = 'sit'; cat.since = now; cat.until = now + 15000 + Math.random() * 15000; }
    else if (cat.mode === 'sit' && now > cat.until) { cat.mode = 'sleep'; cat.since = now; cat.until = now + 12000 + Math.random() * 10000; moveCatToBed(true); }
    else if (cat.mode === 'sleep' && now > cat.until) { cat.mode = 'sit'; cat.since = now; cat.until = now + 18000 + Math.random() * 12000; moveCatToBed(false); }
    if (cat.mode !== 'sleep' && cat.inBed) moveCatToBed(false);

    var frame;
    if (cat.mode === 'sleep') {
      frame = Math.floor(now / 900) % 2 ? 'loaf1' : 'loaf0';
    } else if (cat.mode === 'happy') {
      frame = Math.floor(now / 160) % 2 ? 'happy2' : 'happy';
    } else {
      if (now > cat.nextBlink) { cat.blinkUntil = now + 160; cat.nextBlink = now + 2000 + Math.random() * 3500; }
      var t = Math.floor(now / 420) % 6;
      frame = now < cat.blinkUntil ? 'blink' : ['sit0', 'sit0', 'sit1', 'sit2', 'sit2', 'sit1'][t];
    }
    var hopY = cat.hop.length ? cat.hop.shift() : 0;
    // shadow
    ctx.fillStyle = 'rgba(58,38,48,.2)';
    ctx.fillRect(CAT_OX + KW / 2 - 11, CAT_OY + CAT_FEET, 22, 2);
    var sheet = recoloured('cat', catPalette(cat.coat));
    ctx.drawImage(sheet, frameXY(frame), 0, KW, KH, CAT_OX, CAT_OY + hopY, KW, KH);

    if (cat.mode === 'sleep') {
      var phase = ((now - cat.since) / 1400) % 3;
      if (phase > 0.4) drawZ(ctx, CAT_W - 18, 22 - Math.floor(phase * 2), 4);
      if (phase > 1.4) drawZ(ctx, CAT_W - 12, 14 - Math.floor(phase * 2), 5);
    }
    cat.hearts = cat.hearts.filter(function (h) { return now - h.born < 1300; });
    cat.hearts.forEach(function (h) {
      var age = now - h.born;
      if (age < 0) return;
      drawHeart(ctx, Math.round(h.x), Math.round(CAT_OY - 2 - age / 110));
    });
  }

  // ---------------------------------------------------------------- portrait + previews
  function portrait(el) {
    if (!el) return;
    var c = el.querySelector('canvas.portrait-canvas');
    if (!c) {
      el.textContent = '';
      c = document.createElement('canvas');
      c.className = 'portrait-canvas sprite-canvas';
      c.width = HEAD[2]; c.height = HEAD[3];
      el.appendChild(c);
    }
    var draw = function () {
      var ctx = c.getContext('2d');
      ctx.clearRect(0, 0, HEAD[2], HEAD[3]);
      var tmp = document.createElement('canvas');
      tmp.width = CW; tmp.height = CH;
      drawCharacter(tmp.getContext('2d'), 0, 0, false, 0);
      ctx.drawImage(tmp, HEAD[0], HEAD[1], HEAD[2], HEAD[3], 0, 0, HEAD[2], HEAD[3]);
    };
    if (ready()) draw(); else onReady.push(draw);
  }

  function catPreview(coat) {
    var c = document.createElement('canvas');
    c.width = KW; c.height = KH;
    c.className = 'sprite-canvas cat-preview';
    var draw = function () {
      c.getContext('2d').drawImage(recoloured('cat', catPalette(coat)), frameXY('sit0'), 0, KW, KH, 0, 0, KW, KH);
    };
    if (ready()) draw(); else onReady.push(draw);
    return c;
  }


  // ---------------------------------------------------------------- pixel-art room
  var ROOM = window.COZY_ROOM_META;
  var roomImgs = {}, roomLoaded = 0;
  if (ROOM) {
    ['room-day', 'window-night'].forEach(function (name) {
      var img = new Image();
      img.onload = function () { roomLoaded++; renderRoom(); };
      img.src = 'assets/room/' + name + '.png';
      roomImgs[name] = img;
    });
  }
  var roomLook = { blanket: '#d5b6d9', pattern: 'gingham' };

  function blanketColour(x, y, B, pal, pattern) {
    var lx = x - B.x, ly = y - B.y;
    // pattern decides between base and light
    var on = false;
    if (pattern === 'gingham') {
      var a = (x >> 2) & 1, b = (y >> 2) & 1;
      if (a && b) return pal.shade;
      on = a || b;
    } else if (pattern === 'stripes') {
      on = (ly % 5) < 2;
    } else if (pattern === 'stars') {
      var sx = lx % 11, sy = (ly + (Math.floor(lx / 11) % 2) * 5) % 10;
      if ((sx === 5 && sy >= 3 && sy <= 5) || (sy === 4 && sx >= 4 && sx <= 6)) return '#fff1b8';
    } else if (pattern === 'hearts') {
      var hx = lx % 12, hy = (ly + (Math.floor(lx / 12) % 2) * 6) % 11;
      var heart = ['.x.x.', 'xxxxx', '.xxx.', '..x..'];
      if (hy >= 3 && hy < 7 && hx >= 4 && hx < 9 && heart[hy - 3][hx - 4] === 'x') return '#ffe3ea';
    }
    return on ? pal.light : pal.base;
  }

  function drawBlanket(ctx) {
    var B = ROOM.blanket, base = roomLook.blanket || '#d5b6d9';
    var pal = { base: base, light: light(base, 0.45), shade: shade(base, 0.2), dark: shade(base, 0.38), fold: '#fbf6ff' };
    var x0 = B.x, x1 = B.x + B.w - 1, top = B.y, edge = B.y + (B.top || 5), foldH = 5;
    for (var x = x0; x <= x1; x++) {
      var yb = B.y + B.h - 2 + ((x >> 2) & 1);       // scalloped bottom hem
      for (var y = top; y <= yb; y++) {
        var c;
        if (x === x0 || x === x1 || y === top || y === yb) c = '#3a2630';
        else if (y - top <= foldH) c = y - top === foldH ? pal.dark : (y - top === 1 ? '#ffffff' : pal.fold);   // folded-back sheet
        else if (y === edge) c = pal.dark;                 // edge of the mattress
        else {
          c = blanketColour(x, y, B, pal, roomLook.pattern);
          if (y > edge) {                                   // front of the bed: in shadow
            c = c === pal.base ? pal.shade : (c === pal.light ? pal.base : c);
          } else if (x >= x1 - 1) c = c === pal.base ? pal.shade : c;
        }
        ctx.fillStyle = c;
        ctx.fillRect(x, y, 1, 1);
      }
    }
    ctx.fillStyle = pal.shade;
    [[x0 + 20, top + 10], [x0 + 21, top + 11], [x0 + 48, top + 14], [x0 + 49, top + 15]].forEach(function (p) { ctx.fillRect(p[0], p[1], 3, 1); });
  }

  // Night: purple dusk tint, warm lamp light and a patch of moonlight.
  function drawNight(ctx, lampOn) {
    var W = ROOM.size[0], H = ROOM.size[1], win = ROOM.window, g = ROOM.lampGlow;
    ctx.save();
    ctx.globalCompositeOperation = 'multiply';
    ctx.fillStyle = '#8073b8';
    ctx.fillRect(0, 0, W, H);
    ctx.globalCompositeOperation = 'screen';
    // moonlight falling through the window onto the floor
    ctx.fillStyle = 'rgba(120,140,230,0.22)';
    ctx.beginPath();
    ctx.moveTo(win.x + 4, ROOM.wallY + 2); ctx.lineTo(win.x + win.w - 4, ROOM.wallY + 2);
    ctx.lineTo(win.x + win.w + 30, ROOM.wallY + 46); ctx.lineTo(win.x + 22, ROOM.wallY + 46);
    ctx.closePath(); ctx.fill();
    ctx.fillStyle = 'rgba(150,170,255,0.25)';
    ctx.fillRect(win.x + 4, win.y + 4, win.w - 8, win.h - 8);
    if (lampOn) {
      var grad = ctx.createRadialGradient(g.x, g.y, 2, g.x, g.y + 20, 110);
      grad.addColorStop(0, 'rgba(255,214,130,0.75)');
      grad.addColorStop(0.35, 'rgba(255,190,110,0.32)');
      grad.addColorStop(1, 'rgba(255,170,100,0)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, W, H);
    }
    ctx.restore();
  }

  function drawLamp(ctx, on, night) {
    var L = ROOM.lamp;
    if (on) {
      ctx.fillStyle = '#fff6c2';
      ctx.fillRect(L.x + 3, L.y + 10, 10, 1);
      ctx.fillStyle = night ? 'rgba(255,226,130,0.3)' : 'rgba(255,236,160,0.16)';
      for (var r = 0; r < 14; r++) {
        var half = 5 + Math.floor(r * 0.8);
        ctx.fillRect(L.x + 8 - half, L.y + 11 + r, half * 2, 1);
      }
    } else {
      ctx.fillStyle = '#9b8f7c';
      ctx.fillRect(L.x + 6, L.y + 10, 4, 1);
    }
  }

  function renderRoom() {
    var c = document.getElementById('roomCanvas');
    if (!c || !ROOM || roomLoaded < 2) return;
    var room = c.closest('.room');
    var night = room && room.classList.contains('room-night');
    var lampOn = room && room.classList.contains('lamp-on');
    var ctx = c.getContext('2d');
    ctx.imageSmoothingEnabled = false;
    ctx.clearRect(0, 0, c.width, c.height);
    ctx.drawImage(roomImgs['room-day'], 0, 0);
    if (night) ctx.drawImage(roomImgs['window-night'], 0, 0);
    drawBlanket(ctx);
    if (night) drawNight(ctx, lampOn);
    drawLamp(ctx, lampOn, night);
  }

  function watchRoom() {
    var c = document.getElementById('roomCanvas');
    var room = c && c.closest('.room');
    if (!room || room._cozyWatched) return;
    room._cozyWatched = true;
    new MutationObserver(renderRoom).observe(room, { attributes: true, attributeFilter: ['class'] });
    var lamp = document.getElementById('roomLamp');
    var toggle = function () { var b = document.getElementById('lampToggle'); if (b) b.click(); };
    if (lamp) {
      lamp.addEventListener('click', toggle);
      lamp.addEventListener('keydown', function (e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(); } });
    }
  }


  // Draw the character into an element, optionally with some options swapped
  // (used for the Character page previews and the home card).
  function previewInto(el, overrides, crop) {
    if (!el) return;
    var head = crop === 'head';
    var w = head ? HEAD[2] : CW, h = head ? HEAD[3] : CH;
    var c = el.querySelector('canvas.preview-canvas');
    if (!c) {
      c = document.createElement('canvas');
      c.className = 'preview-canvas sprite-canvas';
      c.width = w; c.height = h;
      el.appendChild(c);
    }
    var draw = function () {
      var saved = look;
      look = Object.assign({}, look, overrides || {});
      var tmp = document.createElement('canvas');
      tmp.width = CW; tmp.height = CH;
      drawCharacter(tmp.getContext('2d'), 0, 0, false, 0, 0);
      look = saved;
      var ctx = c.getContext('2d');
      ctx.clearRect(0, 0, w, h);
      if (head) ctx.drawImage(tmp, HEAD[0], HEAD[1], HEAD[2], HEAD[3], 0, 0, HEAD[2], HEAD[3]);
      else ctx.drawImage(tmp, 0, 0);
    };
    if (ready()) draw(); else onReady.push(draw);
  }
  function fillPreviews(root) {
    (root || document).querySelectorAll('[data-preview]').forEach(function (el) {
      var o = {};
      try { o = JSON.parse(el.getAttribute('data-preview')); } catch (e) {}
      previewInto(el, o, el.getAttribute('data-crop'));
    });
  }

  // ---------------------------------------------------------------- main loop
  function tick() {
    if (document.hidden) return;
    var now = performance.now();
    renderCharacter(now);
    renderCat(now);
  }
  setInterval(tick, 80);

  function setLook(st) {
    look = {
      gender: st.gender, emote: st.emote, outfitStyle: st.outfitStyle, hairStyle: st.hairStyle,
      accessory: st.accessory, skin: st.skin, hair: st.hair, outfit: st.outfit
    };
    cat.coat = st.catCoat || 'ginger';
    roomLook = { blanket: st.blanket, pattern: st.blanketPattern || 'gingham' };
    watchRoom();
    renderRoom();
    tick();
  }

  window.CozySprites = {
    setLook: setLook, portrait: portrait, fillPreviews: fillPreviews,
    figure: function (el) { previewInto(el, {}, 'full'); },
    catMood: function () { return cat.mode; }, catPreview: catPreview, petCat: petCat, hop: hopCharacter,
    CAT_COATS: CAT_COATS.map(function (c) { return [c[0], c[1]]; })
  };
})();
